"use client"

import { useEffect } from "react"
import { useParams } from "next/navigation"
import { useStudentStore } from "@/store/student.store"

export default function ViewStudentPage() {
  const params = useParams()
  const { students, selectedStudent, openViewModal } = useStudentStore()

  const student =
    selectedStudent ||
    students.find((s) => s.AdmissionNo === params.id)

  useEffect(() => {
    if (student) openViewModal(student)
  }, [student, openViewModal])

  if (!student) return null

  return (
    <StudentForm
      title="View Student"
      initialData={student}
      mode="view"
    />
  )
}
